class FakeApiClient:
    """A hand-written test double, standing in for the real HTTP client."""
    def __init__(self, status_code, payload):
        self.status_code = status_code
        self.payload = payload

    def get(self, url):
        return self

    def json(self):
        return self.payload

def make_user_fixture():
    return {'id': 1, 'name': 'John', 'email': 'john@example.com'}

def test_user_fixture():
    user = make_user_fixture()
    assert user['name'] == 'John'
    print('test_user_fixture PASSED')

def test_api_call():
    fake_client = FakeApiClient(status_code=200, payload={'status': 'ok'})
    response = fake_client.get('https://api.example.com')
    assert response.status_code == 200
    assert response.json() == {'status': 'ok'}
    print('test_api_call PASSED')

test_user_fixture()
test_api_call()
